INSERT INTO kb_entries (id, topic, title, body, updated_at) VALUES
  ('kb-services', 'Services', 'What MA3AK does', 'MA3AK helps customers in Lebanon plan events (weddings, engagements, birthdays, corporate events, private parties and more), compare providers and packages, build a budget, and request quotes. The team can also arrange the event with the customer.', '2026-10-16T09:01:00.000Z'),
  ('kb-contact', 'Contact', 'How to reach the team', 'Email: eventsmaak@gmail.com. Phone and WhatsApp: +961 76 620 434. Instagram: @ma3akevents.', '2026-10-16T09:01:00.000Z'),
  ('kb-pricing', 'Pricing', 'Prices', 'Prices shown on the website are estimates from providers’ packages. Demo listings use illustrative prices. Final prices are confirmed by the provider in a quote. Never promise a price or a date.', '2026-10-16T09:01:00.000Z')
INSERT INTO site_settings (key, value, updated_at) VALUES
  ('contact', '{"phone":"+961 76 620 434","whatsapp":"96176620434","email":"eventsmaak@gmail.com","instagram":"ma3akevents","facebook":"","tiktok":"","address":"Lebanon","hours":""}', '2026-10-16T09:01:00.000Z'),
  ('hero', '{"eyebrow":"Event planning in Lebanon","title":"Plan your event, see the real costs, book with confidence","subtitle":"Choose your event, compare providers and packages, and build a budget that updates as you go. Save it, share it, and send it to MA3AK when you’re ready.","primary":"Start planning","secondary":"Browse providers"}', '2026-10-16T09:01:00.000Z'),
  ('budgetIntro', '{"title":"A budget that adds itself up","text":"Add services from providers’ packages and the total updates instantly. Per-guest prices follow your guest count, you’re warned when you go over budget, and cheaper alternatives are one tap away. Prices are estimates until the provider confirms."}', '2026-10-16T09:01:00.000Z'),
  ('howItWorks', '[{"title":"Tell us about your event","text":"Event type, date, area in Lebanon, guests, budget and the style you like."},{"title":"Pick services and packages","text":"Compare providers by category, price and area, and add packages to your plan."},{"title":"Watch the budget","text":"See the estimated total, what’s over budget, and lower-cost options."},{"title":"Request quotes and book","text":"Ask providers for a quote, or send the whole plan to MA3AK to arrange it with you."}]', '2026-10-16T09:01:00.000Z'),
  ('faqs', '[{"q":"Are the prices final?","a":"No. Prices shown are estimates provided by the providers (or illustrative prices on demo listings). Final prices depend on your date, guest count and details, and are confirmed by the provider in a quote."},{"q":"Does it cost anything to plan an event?","a":"Creating an account, saving plans and requesting quotes is free."},{"q":"Is a provider available on my date?","a":"Availability is only confirmed when the provider replies to your quote request. The website never assumes a date is free."},{"q":"Who can see my plan?","a":"Only you. Plans are private by default. If you create a share link, people with the link can view the plan without your contact details or private notes, and you can turn the link off at any time."},{"q":"I’m a provider. How do I get listed?","a":"Create a partner account, fill in your profile, packages and photos, and submit it for review. MA3AK checks every listing before it is published."},{"q":"What are “demo” listings?","a":"Sample providers that show how the planner works while real providers join. They are not real businesses and their prices are illustrative."}]', '2026-10-16T09:01:00.000Z'),
  ('themes', '[{"id":"elegant","name":"Elegant","description":"Ivory, gold and soft candlelight.","colors":["#F4EFE6","#C9A45C","#2B2B2B"]},{"id":"luxury","name":"Luxury","description":"Chandeliers, deep tones and grand florals.","colors":["#1E1B2E","#B8935A","#F2E9DC"]},{"id":"modern","name":"Modern","description":"Clean lines, neon accents and LED walls.","colors":["#111827","#E5E7EB","#7C3AED"]},{"id":"minimal","name":"Minimal","description":"Whites, greenery and plenty of space.","colors":["#FFFFFF","#D1D5DB","#4B5563"]},{"id":"traditional","name":"Traditional Lebanese","description":"Zaffe, dabke, mezze and warm lanterns.","colors":["#7F1D1D","#F59E0B","#FEF3C7"]},{"id":"boho","name":"Boho Garden","description":"Pampas, rattan, string lights under the trees.","colors":["#E9D8C4","#A3765A","#6B7F5A"]},{"id":"beach","name":"Beach Sunset","description":"Sand, white drapes and sunset colours.","colors":["#FDE68A","#FB923C","#0EA5E9"]}]', '2026-10-16T09:01:00.000Z'),
  ('announcement', '{"active":false,"text":""}', '2026-10-16T09:01:00.000Z'),
  ('currency', '"USD"', '2026-10-16T09:01:00.000Z')
